// Consolidate: read the three sources, normalise, and compute what leadership needs to see.
const cfg = $('Config').first().json;
const DAY = 86400000;
const today = new Date(); today.setHours(0, 0, 0, 0);

const toDate = v => { if (!v) return null; const d = new Date(v); return isNaN(d) ? null : d; };
const dayDiff = d => d ? Math.round((d - today) / DAY) : null;
const iso = d => d ? d.toISOString().slice(0, 10) : '';
const rows = name => {
  try { return $(name).all().map(i => i.json).filter(r => r && Object.keys(r).length > 0); }
  catch (e) { return []; }
};
const status = v => {
  const s = String(v || '').trim().toLowerCase();
  return ['green', 'amber', 'red'].includes(s) ? s : 'unknown';
};

const staleAfter = Number(cfg.staleAfterDays) || 10;
const horizon = Number(cfg.milestoneHorizonDays) || 14;

// 1. Workstreams
const workstreams = rows('Read Workstreams').filter(r => r.Workstream).map(r => {
  const due = toDate(r['Milestone Due']);
  const updated = toDate(r['Last Updated']);
  const pct = String(r['% Complete'] ?? '').replace('%', '').trim();
  const daysToDue = dayDiff(due);
  const sinceUpdate = updated ? -dayDiff(updated) : null;
  return {
    name: r.Workstream,
    owner: r.Owner || 'Unassigned',
    status: status(r.Status),
    pctComplete: pct === '' ? null : Number(pct),
    progress: r['This Week Progress'] || '',
    milestone: r['Next Milestone'] || '',
    milestoneDue: iso(due),
    daysToDue,
    blockers: r.Blockers || '',
    daysSinceUpdate: sinceUpdate,
    overdue: daysToDue !== null && daysToDue < 0 && pct !== '100',
    stale: sinceUpdate !== null && sinceUpdate > staleAfter,
    noUpdate: updated === null,
  };
});

// 2. Risks and decisions
const log = rows('Read Risks and Decisions').filter(r => r.Description).map(r => {
  const needBy = toDate(r['Decision Needed By']);
  return {
    id: r.ID || '',
    type: String(r.Type || '').trim().toLowerCase() === 'decision' ? 'decision' : 'risk',
    description: r.Description,
    owner: r.Owner || 'Unassigned',
    severity: String(r.Severity || '').trim().toLowerCase() || 'unrated',
    needBy: iso(needBy),
    daysToNeedBy: dayDiff(needBy),
    status: String(r.Status || 'Open').trim().toLowerCase(),
    options: r['Mitigation / Options'] || '',
  };
}).filter(r => r.status !== 'closed');

const sevRank = { high: 0, medium: 1, low: 2 };
const risks = log.filter(r => r.type === 'risk')
  .sort((a, b) => (sevRank[a.severity] ?? 3) - (sevRank[b.severity] ?? 3));
const decisions = log.filter(r => r.type === 'decision')
  .sort((a, b) => (a.daysToNeedBy ?? 9999) - (b.daysToNeedBy ?? 9999));

// 3. Calendar: only events that look like leadership checkpoints
const kw = new RegExp(cfg.calendarKeywords || 'steering|review|board|milestone|decision|go-live|deadline', 'i');
const events = rows('Read Calendar').map(e => {
  const start = (e.start && (e.start.dateTime || e.start.date)) || e.start || '';
  return { title: e.summary || e.title || '', start: String(start).slice(0, 16).replace('T', ' ') };
}).filter(e => e.title && kw.test(e.title)).slice(0, 10);

// 4. Roll-up
const count = s => workstreams.filter(w => w.status === s).length;
const facts = {
  weekOf: iso(today),
  counts: {
    workstreams: workstreams.length,
    green: count('green'), amber: count('amber'), red: count('red'), unknown: count('unknown'),
    overdueMilestones: workstreams.filter(w => w.overdue).length,
    staleUpdates: workstreams.filter(w => w.stale || w.noUpdate).length,
    openRisks: risks.length,
    highRisks: risks.filter(r => r.severity === 'high').length,
    openDecisions: decisions.length,
    decisionsDueThisWeek: decisions.filter(d => d.daysToNeedBy !== null && d.daysToNeedBy <= 7).length,
  },
  needsAttention: workstreams.filter(w => w.status === 'red' || w.overdue),
  watchList: workstreams.filter(w => w.status === 'amber' && !w.overdue),
  upcomingMilestones: workstreams
    .filter(w => w.daysToDue !== null && w.daysToDue >= 0 && w.daysToDue <= horizon)
    .sort((a, b) => a.daysToDue - b.daysToDue),
  staleOwners: workstreams.filter(w => w.stale || w.noUpdate).map(w => ({ name: w.name, owner: w.owner, daysSinceUpdate: w.daysSinceUpdate })),
  workstreams, risks, decisions, events,
};

// 5. Request for the AI summary (kept separate so the numbers above never depend on the model)
const system = 'You write the executive summary of a weekly operational status report for a leadership team. ' +
  'Use only the facts in the data provided. Do not invent numbers, names, causes or dates. If something is unknown, say so. ' +
  'Plain, direct language. Respond with JSON only, no preamble, in this shape: ' +
  '{"headline": string (maximum 2 sentences), "attention": string[] (maximum 3 items leadership must act on or decide this week), ' +
  '"watch": string[] (maximum 3 items likely to become problems within two weeks)}.';

const slim = {
  weekOf: facts.weekOf, counts: facts.counts,
  needsAttention: facts.needsAttention.map(w => ({ name: w.name, owner: w.owner, status: w.status, overdue: w.overdue, blockers: w.blockers, progress: w.progress })),
  watchList: facts.watchList.map(w => ({ name: w.name, owner: w.owner, blockers: w.blockers, milestone: w.milestone, milestoneDue: w.milestoneDue })),
  decisions: decisions.slice(0, 8).map(d => ({ id: d.id, description: d.description, owner: d.owner, needBy: d.needBy, options: d.options })),
  highRisks: risks.filter(r => r.severity === 'high').map(r => ({ id: r.id, description: r.description, owner: r.owner, options: r.options })),
  upcomingMilestones: facts.upcomingMilestones.map(w => ({ name: w.name, milestone: w.milestone, due: w.milestoneDue })),
  staleOwners: facts.staleOwners,
};

return [{ json: {
  facts,
  aiRequest: {
    model: cfg.model,
    max_tokens: 1000,
    system,
    messages: [{ role: 'user', content: 'Weekly data:\n' + JSON.stringify(slim) }],
  },
} }];

// Build Report: merge the numbers with the AI summary (or a rule-based fallback) and render email + Slack text.
const cfg = $('Config').first().json;
const facts = $('Consolidate').first().json.facts;
const c = facts.counts;

// AI summary is optional. If the call failed or the node is disabled, fall back to rules.
let ai = null;
try {
  const raw = $input.first().json.content[0].text;
  ai = JSON.parse(raw.replace(/```json|```/g, '').trim());
} catch (e) { ai = null; }

const plural = (n, w) => `${n} ${w}${n === 1 ? '' : 's'}`;
const fallbackHeadline = `${c.green} green, ${c.amber} amber and ${c.red} red across ${plural(c.workstreams, 'workstream')}. ` +
  `${plural(c.overdueMilestones, 'milestone')} overdue and ${plural(c.openDecisions, 'decision')} open.`;
const fallbackAttention = [
  ...facts.needsAttention.map(w => `${w.name} (${w.owner}): ${w.status === 'red' ? 'red' : 'overdue'}${w.blockers ? '. Blocker: ' + w.blockers : ''}`),
  ...facts.decisions.filter(d => d.daysToNeedBy !== null && d.daysToNeedBy <= 7).map(d => `Decision ${d.id} needed by ${d.needBy}: ${d.description}`),
].slice(0, 3);
const fallbackWatch = facts.watchList.map(w => `${w.name} (${w.owner}) is amber${w.blockers ? '. ' + w.blockers : ''}`).slice(0, 3);

const headline = (ai && ai.headline) || fallbackHeadline;
const attention = (ai && Array.isArray(ai.attention) && ai.attention) || fallbackAttention;
const watch = (ai && Array.isArray(ai.watch) && ai.watch) || fallbackWatch;

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const dot = { green: '#2e7d32', amber: '#ed8e00', red: '#c62828', unknown: '#757575' };
const label = { green: 'Green', amber: 'Amber', red: 'Red', unknown: 'No status' };

// ---------- Markdown ----------
const md = [];
md.push(`# ${cfg.reportTitle}: week of ${facts.weekOf}`, '');
md.push(`**${headline}**`, '');
md.push(`| Green | Amber | Red | Overdue milestones | Open decisions | High risks |`, `|---|---|---|---|---|---|`);
md.push(`| ${c.green} | ${c.amber} | ${c.red} | ${c.overdueMilestones} | ${c.openDecisions} | ${c.highRisks} |`, '');
md.push('## Needs leadership attention', ...(attention.length ? attention.map(a => `- ${a}`) : ['- Nothing flagged this week.']), '');
md.push('## Watch list', ...(watch.length ? watch.map(a => `- ${a}`) : ['- Nothing on the watch list.']), '');
md.push('## Workstreams', '', '| Workstream | Owner | Status | Done | Progress this week | Next milestone | Due |', '|---|---|---|---|---|---|---|');
facts.workstreams.forEach(w => md.push(`| ${w.name} | ${w.owner} | ${label[w.status]}${w.overdue ? ' (overdue)' : ''} | ${w.pctComplete ?? ''}${w.pctComplete !== null ? '%' : ''} | ${w.progress} | ${w.milestone} | ${w.milestoneDue} |`));
md.push('', '## Decisions needed', '');
if (facts.decisions.length) { md.push('| ID | Decision | Owner | Needed by | Options |', '|---|---|---|---|---|'); facts.decisions.forEach(d => md.push(`| ${d.id} | ${d.description} | ${d.owner} | ${d.needBy} | ${d.options} |`)); } else { md.push('None open.'); }
md.push('', '## Open risks', '');
if (facts.risks.length) { md.push('| ID | Risk | Severity | Owner | Mitigation |', '|---|---|---|---|---|'); facts.risks.forEach(r => md.push(`| ${r.id} | ${r.description} | ${r.severity} | ${r.owner} | ${r.options} |`)); } else { md.push('None open.'); }
md.push('', '## Next 7 days: leadership checkpoints', ...(facts.events.length ? facts.events.map(e => `- ${e.start}: ${e.title}`) : ['- None in the calendar.']));
if (facts.staleOwners.length) md.push('', '## Updates missing or stale', ...facts.staleOwners.map(s => `- ${s.name} (${s.owner}): ${s.daysSinceUpdate === null ? 'no update date recorded' : s.daysSinceUpdate + ' days since last update'}`));
md.push('', `_${ai ? 'Summary drafted with AI from the data above.' : 'Summary generated by rules, without AI.'} All figures come directly from the source sheets._`);

// ---------- HTML ----------
const th = 'style="text-align:left;padding:6px 8px;border-bottom:2px solid #ddd;font-size:12px;color:#555"';
const td = 'style="padding:6px 8px;border-bottom:1px solid #eee;font-size:13px;vertical-align:top"';
const table = (heads, body) => `<table style="border-collapse:collapse;width:100%;margin:6px 0 18px"><tr>${heads.map(h => `<th ${th}>${h}</th>`).join('')}</tr>${body}</table>`;
const row = cells => `<tr>${cells.map(x => `<td ${td}>${x}</td>`).join('')}</tr>`;
const chip = s => `<span style="color:${dot[s]};font-weight:600">&#9679; ${label[s]}</span>`;
const stat = (n, l, col) => `<td style="padding:10px 14px;text-align:center;border:1px solid #eee"><div style="font-size:22px;font-weight:700;color:${col || '#222'}">${n}</div><div style="font-size:11px;color:#666">${l}</div></td>`;
const ul = items => `<ul style="margin:6px 0 16px;padding-left:20px;font-size:14px">${items.map(i => `<li style="margin-bottom:4px">${esc(i)}</li>`).join('')}</ul>`;
const h2 = t => `<h2 style="font-size:15px;margin:22px 0 4px;color:#222">${t}</h2>`;

let html = `<div style="font-family:-apple-system,Segoe UI,Helvetica,Arial,sans-serif;max-width:820px;color:#222">`;
html += `<h1 style="font-size:20px;margin-bottom:4px">${esc(cfg.reportTitle)}</h1><div style="color:#666;font-size:13px;margin-bottom:14px">Week of ${facts.weekOf}</div>`;
html += `<p style="font-size:15px;line-height:1.5">${esc(headline)}</p>`;
html += `<table style="border-collapse:collapse;margin:10px 0 6px"><tr>${stat(c.green, 'Green', dot.green)}${stat(c.amber, 'Amber', dot.amber)}${stat(c.red, 'Red', dot.red)}${stat(c.overdueMilestones, 'Overdue milestones')}${stat(c.openDecisions, 'Open decisions')}${stat(c.highRisks, 'High risks')}</tr></table>`;
html += h2('Needs leadership attention') + (attention.length ? ul(attention) : '<p style="font-size:14px">Nothing flagged this week.</p>');
html += h2('Watch list') + (watch.length ? ul(watch) : '<p style="font-size:14px">Nothing on the watch list.</p>');
html += h2('Workstreams') + table(['Workstream', 'Owner', 'Status', 'Done', 'Progress this week', 'Next milestone', 'Due'],
  facts.workstreams.map(w => row([esc(w.name), esc(w.owner), chip(w.status) + (w.overdue ? ' <b style="color:#c62828">overdue</b>' : ''), w.pctComplete !== null ? w.pctComplete + '%' : '', esc(w.progress), esc(w.milestone), esc(w.milestoneDue)])).join(''));
html += h2('Decisions needed') + (facts.decisions.length ? table(['ID', 'Decision', 'Owner', 'Needed by', 'Options'], facts.decisions.map(d => row([esc(d.id), esc(d.description), esc(d.owner), esc(d.needBy), esc(d.options)])).join('')) : '<p style="font-size:14px">None open.</p>');
html += h2('Open risks') + (facts.risks.length ? table(['ID', 'Risk', 'Severity', 'Owner', 'Mitigation'], facts.risks.map(r => row([esc(r.id), esc(r.description), esc(r.severity), esc(r.owner), esc(r.options)])).join('')) : '<p style="font-size:14px">None open.</p>');
html += h2('Next 7 days: leadership checkpoints') + (facts.events.length ? ul(facts.events.map(e => `${e.start}: ${e.title}`)) : '<p style="font-size:14px">None in the calendar.</p>');
if (facts.staleOwners.length) html += h2('Updates missing or stale') + ul(facts.staleOwners.map(s => `${s.name} (${s.owner}): ${s.daysSinceUpdate === null ? 'no update date recorded' : s.daysSinceUpdate + ' days since last update'}`));
html += `<p style="font-size:11px;color:#888;margin-top:24px">${ai ? 'Summary drafted with AI from the data above.' : 'Summary generated by rules, without AI.'} All figures come directly from the source sheets.</p></div>`;

const subject = `${cfg.reportTitle} | Week of ${facts.weekOf}` + (c.red > 0 ? ` | ${c.red} red` : '') + (c.decisionsDueThisWeek > 0 ? ` | ${c.decisionsDueThisWeek} decision${c.decisionsDueThisWeek === 1 ? '' : 's'} due` : '');
const slackText = `*${cfg.reportTitle}, week of ${facts.weekOf}*\n${headline}\n:large_green_circle: ${c.green}  :large_yellow_circle: ${c.amber}  :red_circle: ${c.red}  |  Decisions open: ${c.openDecisions}  |  High risks: ${c.highRisks}\n` +
  (attention.length ? '*Needs attention*\n' + attention.map(a => `• ${a}`).join('\n') : '');

return [{ json: { subject, html, markdown: md.join('\n'), slackText, aiUsed: !!ai } }];
